import type { CSSProperties } from 'react';

// Frame sprites generated by scripts/build-media.mjs (one frame every 2 s, 10 columns).
const SPRITES: Record<string, { url: string; every: number; cols: number; rows: number; count: number; w: number; h: number; duration: number }> = {
  'coffee-run': { url: '/media/coffee-run-scrub.jpg', every: 2, cols: 10, rows: 10, count: 93, w: 240, h: 100, duration: 184.6 },
  'sintel-trailer': { url: '/media/sintel-trailer-scrub.jpg', every: 2, cols: 10, rows: 3, count: 27, w: 240, h: 136, duration: 52.2 },
};

/**
 * CSS for one frame of a stream's sprite at time t (seconds of the item's own
 * timeline, mapped onto the fixture stream), scaled to `width` pixels wide.
 */
export function frameStyle(stream: string, t: number, width: number): CSSProperties {
  const s = SPRITES[stream] ?? SPRITES['coffee-run'];
  const local = ((t % s.duration) + s.duration) % s.duration;
  const i = Math.min(s.count - 1, Math.floor(local / s.every));
  const scale = width / s.w;
  return {
    width,
    height: Math.round(s.h * scale),
    backgroundImage: `url(${s.url})`,
    backgroundSize: `${s.cols * s.w * scale}px ${s.rows * s.h * scale}px`,
    backgroundPosition: `${-(i % s.cols) * s.w * scale}px ${-Math.floor(i / s.cols) * s.h * scale}px`,
  };
}

export const spriteAspect = (stream: string) => {
  const s = SPRITES[stream] ?? SPRITES['coffee-run'];
  return s.w / s.h;
};
